const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=o=>JSON.stringify(o,null,2), when=t=>t?new Date(t).toLocaleString():'Not checked yet';
let auth={},view=null,data={endpoints:[],hosts:[],links:[],experiments:[],events:[],jobs:[]},session=null,remote=null,installationUpdates=null,busy=false,toastTimer,polling=false;
const screens={agents:'Agents',work:'Work',connections:'Connections',hosts:'Machines',experiments:'Experiments',activity:'Activity',settings:'Access'};
async function api(path,method='GET',body){const r=await fetch(path.startsWith('/')?path:`/api/v1/${path}`,{method,headers:{'Content-Type':'application/json',...(auth.csrf?{'X-CSRF-Token':auth.csrf}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const value=await r.json();if(!r.ok)throw Error(value.error||`Request failed (${r.status})`);return value;}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',7000);}
let actions=Promise.resolve();function act(f){const task=actions.then(async()=>{busy=true;try{await f();}catch(e){toast(e.message);}finally{busy=false;}});actions=task.catch(()=>{});return task;}
async function cmd(patch,redraw=true){if(!view)return;try{view=await api(`views/${view.id}/commands`,'POST',{expected_revision:view.revision,controller:'human',commands:Object.entries(patch).map(([field,value])=>({op:'set',field,value}))});if(redraw)await render();}catch(e){view=await api(`views/${view.id}`);await render();throw e;}}
async function load(){const results=await Promise.all(['endpoints','hosts','links','experiments','activity','jobs','sessions'].map(async k=>{try{return [k,await api(k)]}catch(e){return[k,{error:e.message}]}}));for(const[k,v]of results){if(v.error){toast(`Could not refresh ${k}. Previously loaded information is still shown.`);}else Object.assign(data,v);}}
function field(label,name,value='',type='text',hint=''){return `<label class="field"><span>${esc(label)}</span><input aria-label="${esc(label)}" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='password'?'autocomplete="new-password"':''}>${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
function area(label,name,value='',hint=''){return `<label class="field"><span>${esc(label)}</span><textarea aria-label="${esc(label)}" id="f-${name}" name="${name}" spellcheck="false">${esc(value)}</textarea>${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
function select(label,name,options,value){return `<label class="field"><span>${esc(label)}</span><select aria-label="${esc(label)}" id="f-${name}" name="${name}">${options.map(([k,t])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function supports(e,id){if(!e.management)return false;const ops=e.observation?.operations;if(ops)return ops.some(o=>o.id===id);if(['memory','scheduler','native-config','updates'].includes(id))return false;return id!=='validate-config'||e.management.provider==='agent-instance';}
function endpoint(){return data.endpoints.find(e=>e.id===view.selected_id);}
function title(){const e=endpoint();return view.screen==='agents'&&e?e.label:screens[view.screen];}
function connectionHealth(e){const checks=[e.management?e.observation:null,e.acp?e.acp_observation:null].filter(Boolean);return checks.some(o=>o.health==='unavailable')?'unavailable':checks.some(o=>o.health==='reachable')?'reachable':'unknown';}
function lastChecked(e){return Math.max(e.management?e.observation?.observed_at||0:0,e.acp?e.acp_observation?.observed_at||0:0);}
function badge(e){const o={health:connectionHealth(e)};return `<span class="badge ${o?.health==='reachable'?'ok':o?.health==='unavailable'?'warn':''}">${o?.health==='reachable'?'Connected':o?.health==='unavailable'?'Needs attention':'Not checked'}</span>`;}
function empty(title,body,action,label){return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(body)}</p>${action?`<button class="primary" data-action="${action}">${esc(label)}</button>`:''}</div>`;}
function heading(name,desc,actions=''){return `<div class="heading"><div><div class="eyebrow">Independent agents, together</div><h1>${esc(name)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></div>`;}
function cards(es){return `<div class="cards">${es.map(e=>`<article class="card"><div class="card-head"><div><div class="eyebrow">${esc(e.kind||'agent')}</div><h2>${esc(e.label)}</h2></div>${badge(e)}</div><p class="muted">${esc(e.management?.base_url||e.ui_url||e.acp?.command||'ACP connection')}</p><small>${e.acp?'ACP attached':'Conversation connection not attached'}${e.management?` · ${e.management.access==='manage'?'Manage and observe':'Observe'}`:''}<br>${when(lastChecked(e))}</small><div class="actions"><button data-open="${e.id}">Open</button>${e.ui_url?`<a href="${esc(e.ui_url)}" target="_blank" rel="noopener">Own dashboard ↗</a>`:''}</div></article>`).join('')}</div>`;}
function agents(){const e=endpoint();if(e)return agent(e);const all=data.endpoints.filter(e=>e.kind==='agent'||!e.kind);const shown=all.filter(e=>`${e.label} ${e.management?.base_url||''}`.toLowerCase().includes(view.filter.toLowerCase()));return heading('Your agents, at a glance.','Connect an existing agent or install another on one of your machines.',`<button data-action="install">Create agent</button><button class="primary" data-action="connect">Connect existing</button>`)+`<div class="statline"><span><b>${all.length}</b>agents</span><span><b>${all.filter(e=>connectionHealth(e)==='reachable').length}</b>connected</span><span><b>${data.hosts.length}</b>machines</span></div><div class="toolbar"><input id="search" aria-label="Find an agent" placeholder="Find an agent…" value="${esc(view.filter)}"><button data-action="refresh-all">Check connections</button></div>`+(all.length?cards(shown):empty('Bring your first agent here.','Its own installation, conversations, and identity stay with it. This surface connects to the interfaces it offers.','connect','Connect an agent'));}
function agent(e){const tabs=[['overview','Overview'],...(supports(e,'updates')?[['updates','Updates']]:[]),...(supports(e,'work')?[['work','Work']]:[]),...(supports(e,'scheduler')?[['background','Background work']]:[]),...(supports(e,'memory')?[['memory','Memory']]:[]),...(supports(e,'sessions')?[['sessions','Sessions']]:[]),['chat','Talk'],...(supports(e,'config')?[['configuration','Configuration']]:[]),['inspect','Details'],...(e.ui_url?[['embedded','Dashboard']]:[])];let body='';
 if(view.tab==='overview')body=`<div class="split"><section class="panel stack"><h2>${esc(e.label)}</h2>${badge(e)}<p>${esc(e.notes||'This agent runs independently. Its attached capabilities determine what you can do here.')}</p><div class="row"><span>Management</span><span>${esc(e.management?.access||'Not attached')}</span></div><div class="row"><span>ACP</span><span>${e.acp?e.acp_observation?.health==='reachable'?'Connected':e.acp_observation?.health==='unavailable'?'Needs attention':'Attached · not checked':'Not attached'}</span></div><div class="row"><span>Last checked</span><span>${when(lastChecked(e))}</span></div>${[e.management?e.observation:null,e.acp?e.acp_observation:null].filter(o=>o?.error).map(o=>`<p class="error">${esc(o.error)}</p>`).join('')}<div class="actions">${e.management?'<button data-action="inspect">Check connection</button>':''}${e.acp?'<button data-action="probe">Check ACP</button>':''}${e.ui_url?`<a href="${esc(e.ui_url)}" target="_blank" rel="noopener">Open its own dashboard ↗</a>`:''}</div></section><aside class="panel stack"><h3>Available here</h3><p class="muted">${e.acp?'Talk through standard ACP, with session restore when supported. ':''}${e.management?'Read observations through its management provider. ':''}${e.management?.access==='manage'?'Apply configuration or lifecycle changes with this connection’s separate grant.':''}</p>${e.management?.access==='manage'&&supports(e,'lifecycle')?'<div class="actions"><button data-lifecycle="start">Start agent</button><button data-lifecycle="stop">Stop agent</button></div>':''}<button data-action="edit">Edit connection</button></aside></div>`;
 else if(view.tab==='chat')body=e.acp?chat(e):empty('Attach an ACP command to talk here.','Management access alone does not create a conversation. Use the agent’s own interface or add its ACP attach command.','edit','Edit connection');
 else if(view.tab==='embedded')body=`<div class="notice">This is the agent’s own interface. ${view.draft.embedded_route?'<button data-action="show-agent-screen">Show selected agent screen</button>':''} Its embedding settings must allow this Observatory address; you may need to sign in there too. <a href="${esc(e.ui_url)}" target="_blank" rel="noopener">Open separately ↗</a></div><iframe title="${esc(e.label)} dashboard" class="embedded" src="${esc(e.ui_url)}"></iframe>`;
 else if(view.tab==='work')body=`<div class="panel"><div class="actions"><h2>Work owned by this agent</h2><button data-operation="work">Load work</button></div><div id="remote">${remote?renderWork(remote,e):'<p class="muted">Load the agent’s current responsibilities and commitments.</p>'}</div></div>`;
 else if(view.tab==='memory')body=memoryPanel(e);
 else if(view.tab==='background')body=backgroundPanel(e);
 else if(view.tab==='configuration')body=e.management?.access==='manage'?`<section class="panel stack"><h2>Agent configuration</h2><p class="muted">Load its current configuration, edit, then validate before applying. The agent service remains the source of truth.</p><div class="actions"><button data-operation="config">Load configuration</button><button data-action="edit">Connection settings</button>${e.ui_url&&supports(e,'native-config')?'<button data-own-screen="configuration">Model &amp; capabilities in agent settings</button>':''}</div>${remote?area('Configuration JSON','configuration',view.draft.configuration||pretty(remote.config||remote))+'<div class="actions">'+(supports(e,'validate-config')?'<button data-action="validate-config">Validate</button>':'')+'<button class="primary" data-action="apply-config">Apply configuration</button></div>':''}</section>`:empty('This connection can observe.','Editing requires a separate management grant from this agent.','edit','Edit connection');
 else if(view.tab==='updates')body=updatesPanel(e);
 else if(view.tab==='sessions')body=`<section class="panel stack"><h2>Agent sessions</h2><button data-operation="sessions">Load sessions</button>${remote?`<pre class="detail">${esc(pretty(remote))}</pre>`:'<p class="muted">The agent decides which session information this connection may see.</p>'}</section>`;
 else body=`<section class="panel stack"><h2>Connection details</h2><pre class="detail">${esc(pretty(e))}</pre><button class="danger" data-action="detach">Detach from Observatory</button><small>Detaching removes this inventory entry. The independent service keeps running.</small></section>`;
 return heading(e.label,'One independent agent, wherever you meet it.','<button data-action="back">All agents</button>')+`<div class="tabs">${tabs.map(([id,label])=>`<button class="${view.tab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div>`+body;
}
function renderWork(value,e){const rows=Array.isArray(value)?value:(value.work||value.items||[]);return Array.isArray(rows)&&rows.length?rows.map(w=>`<article class="work-item"><span class="badge">${esc(w.status||w.state||'proposed')}</span><h3>${esc(w.title||w.summary||w.id)}</h3><div class="markdown">${renderMarkdown(w.goal||w.description||w.intent||'')}</div><small>${esc(w.id)}</small>${w.completion_contract?`<p class="muted">${w.completion_contract.closure?"Accepted by requester":`${(w.completion_contract.brief?.acceptance_criteria||[]).length} acceptance criteria · ${(w.completion_contract.artifact_set?.artifacts||[]).length} delivered versions · ${(w.completion_contract.brief?.reviewer_actors||[]).length} named reviewers`}</p>`:""}${e?.management?.provider==='agent-instance'?ownScreen(e,"work","Inspect work and review",w.id):""}<details><summary>Evidence and responsibility</summary><pre class="detail">${esc(pretty(w))}</pre></details></article>`).join(''):`<p class="muted">${rows.length===0?'No work recorded yet.':'This provider uses a different work format.'}</p><details><summary>Inspect response</summary><pre class="detail">${esc(pretty(value))}</pre></details>`;}
function ownScreen(e,route,label,workId=""){return e.ui_url?`<button data-own-screen="${route}" data-endpoint="${esc(e.id)}" data-work="${esc(workId)}">${label}</button>`:'';}
function updatesPanel(e){const u=remote?.schema==='constellation.installation-updates/1'?remote:null;return `<section class="panel stack"><h2>Installation updates</h2><div class="actions"><button data-operation="updates">Refresh status</button>${e.management?.access==='manage'?'<button data-update-action="check">Check now</button><button class="primary" data-update-action="update">Update now</button>':''}${ownScreen(e,'updates','Update preferences')}</div>${u?`<p>${esc(u.helper?.state||'No check yet')}${u.helper_connected?'':' · Update helper offline'}</p>${u.helper?.error?`<p class="error">${esc(u.helper.error)}</p>`:''}<p class="muted">${u.policy.check_minutes?'Checks every '+esc(u.policy.check_minutes)+' minutes':'Manual checks'} · ${esc(u.policy.channel)} · Agent-initiated updates ${u.policy.agent_initiated?'enabled':'disabled'}</p>${(u.helper?.components||[]).map(c=>`<div class="row"><span>${esc(c.id)}</span><span>${esc(c.version)}${c.available?' → '+esc(c.target_version):''}</span></div>`).join('')}`:'<p>Load this installation’s update status. Its own helper performs updates and recovery.</p>'}</section>`;}
function memoryPanel(e){if(!supports(e,'memory'))return empty('Memory is not available here.','Inspect this connection to discover its current capabilities.','inspect','Check connection');const items=remote?.items||[];return `<section class="panel stack"><div class="actions"><h2>What this agent remembers</h2><button data-operation="memory">Load memories</button>${ownScreen(e,'memory','Manage in agent dashboard')}</div><p class="muted">Attributed knowledge stays with this individual and its original audience. Conflicting accounts remain visible until explicitly resolved.</p>${remote?.load_error?`<p class="error">${esc(remote.load_error)}</p>`:!remote?'<p>Load the current records from the agent.</p>':!items.length?'<p>No memories recorded yet.</p>':items.map(m=>`<article class="work-item"><span class="badge ${m.state==='conflicted'?'warn':''}">${esc(m.state)}</span><h3>${esc(m.key)}</h3><small>${m.audience?.kind==='conversation'?`Conversation · ${esc(m.audience.provider_id)} / ${esc(m.audience.conversation_id)}`:'Owner context'} · Revision ${esc(m.revision)}</small>${(m.candidates||[]).map(c=>`<div class="memory-candidate"><small>${c.id===m.selected_candidate_id?'Selected account':m.state==='conflicted'?'Unresolved alternative':'Earlier account'}</small><div class="markdown">${renderMarkdown(c.statement)}</div><small>${c.sources.length} attributed source${c.sources.length===1?'':'s'}</small></div>`).join('')}<button data-memory-details="${esc(m.id)}">${view.draft.memory_details===m.id?'Hide':'Show'} sources</button>${view.draft.memory_details===m.id?`<div class="memory-sources">${m.candidates.flatMap(c=>(c.sources||[]).map(source=>`<p><b>${esc(c.statement)}</b><br>${esc(source.note)}<br><small>${when(source.recorded_at)} · ${esc(source.recorded_by)}${source.source?.conversation_id?' · '+esc(source.source.provider_id)+' / '+esc(source.source.conversation_id):''}</small></p>`)).join('')}</div>`:''}</article>`).join('')}</section>`;}
function backgroundPanel(e){if(!supports(e,'scheduler'))return empty('Background work is not available here.','Inspect this connection to discover its current capabilities.','inspect','Check connection');const runs=remote?.runs||[];return `<section class="panel stack"><div class="actions"><h2>Work continuing with this agent</h2><button data-operation="scheduler">Load background work</button>${ownScreen(e,'work','Manage work and limits')}</div><p class="muted">Runs retain their own sessions and explicit budgets. A report awaits review; it is not proof of completion.</p>${remote?.load_error?`<p class="error">${esc(remote.load_error)}</p>`:remote?.settings?`<div class="statline"><span><b>${remote.settings.enabled?remote.settings.paused?'Paused':'Enabled':'Disabled'}</b>Background execution</span><span><b>${esc(remote.settings.concurrency)}</b>Concurrent runs</span><span><b>${esc(remote.limits?.turns_per_run||1)}</b>Maximum turns per authorization</span></div>${runs.length?runs.map(r=>`<article class="work-item"><span class="badge">${esc(r.state.replaceAll('_',' '))}</span><h3>${esc(r.work_snapshot?.title||r.work_id)}</h3><p>${esc((typeof r.progress==='string'?r.progress:r.progress?.summary)||r.reason||'')}</p><small>${esc(r.turns_completed||0)} / ${esc(r.budget?.max_turns||1)} turns · ${esc(r.tool_calls||0)} tool calls · ${esc(r.budget?.max_seconds)} seconds authorized${r.resume_session?' · Resumed saved session':''}</small>${r.report?`<div><button data-run-report="${esc(r.id)}">${view.draft.run_report===r.id?'Hide':'Read'} report</button></div>${view.draft.run_report===r.id?`<div class="markdown">${renderMarkdown(r.report)}</div><small>Agent report · Requires independent review</small>`:''}`:''}</article>`).join(''):'<p>No background runs recorded.</p>'}`:'<p>Load the current runs and authorization settings.</p>'}</section>`;}
async function loadOptionalView(){
 if(view.screen!=='agents'||view.modal||remote)return;
 const e=endpoint(),tab=view.tab,operation=tab==='memory'?'memory':tab==='background'?'scheduler':tab==='updates'?'updates':null;
 if(!e||!operation||!supports(e,operation))return;
 let value;try{value=await api(`endpoints/${e.id}/operations/${operation}`,'POST',{});}catch(err){value={load_error:err.message};}
 if(view.screen==='agents'&&view.selected_id===e.id&&view.tab===tab&&!view.modal)remote=value;
}
function showAgentScreen(){const frame=$('iframe.embedded'),e=endpoint(),route=view.draft.embedded_route;if(!frame||!e?.ui_url||!['work','memory','configuration','updates'].includes(route))return;frame.contentWindow.postMessage({protocol:'agent-instance.ui/1',id:crypto.randomUUID(),type:'command',command:{type:'navigate',route,...(view.draft.embedded_work?{work_id:view.draft.embedded_work}:{})}},new URL(e.ui_url).origin);}
function permissionCards(){return (session?.permissions||[]).map(p=>`<section class="permission-card" aria-label="Action needs your approval"><h3>Review this action</h3><p>${esc(p.tool_call?.title||'The agent requested permission')}</p><small>Expires ${when(p.expires_at)}. Only the person who started this turn can decide.</small><button type="button" id="permission-${esc(p.id)}-details" data-permission-details="${esc(p.id)}" aria-expanded="${view.permission_details===p.id}">${view.permission_details===p.id?'Hide':'Show'} action details</button>${view.permission_details===p.id?`<pre class="detail">${esc(pretty(p.tool_call))}</pre>`:''}<div class="actions">${p.options.map((o,i)=>`<button type="button" id="permission-${esc(p.id)}-option-${i}" data-permission="${esc(p.id)}" data-option="${esc(o.optionId)}">${esc(o.name)}${o.kind.endsWith('_always')?' (remember this policy)':''}</button>`).join('')}<button type="button" id="permission-${esc(p.id)}-cancel" data-permission="${esc(p.id)}">Cancel request</button></div></section>`).join('');}
function elicitationCards(){return (session?.elicitations||[]).map(p=>{
 const actions=`<button type="button" data-form-decision="decline" data-form-id="${esc(p.id)}">Decline</button><button type="button" data-form-decision="cancel" data-form-id="${esc(p.id)}">Cancel request</button>`;
 if(p.mode==='url')return `<section class="permission-card elicitation-url"><h3>${esc(p.agent)} requests an external step</h3><p>${esc(p.message)}</p><strong>${esc(p.host)}</strong><p class="external-url">${esc(p.url)}</p><p>Open the provider page to continue. Enter credentials there.</p><div class="actions"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer" data-form-open="${esc(p.id)}">Open and continue</a>${actions}</div></section>`;
 const draft=view.elicitation_drafts?.[p.id]||{};
 const fields=Object.entries(p.schema.properties).map(([name,f])=>{
  const value=Object.hasOwn(draft,name)?draft[name]:f.default;
  const required=(p.schema.required||[]).includes(name)?'required':'';
  const common=`data-form-field="${esc(name)}" name="${esc(name)}" autocomplete="off"`;
  const choice=f.type==='array'?f.items:f;
  const options=(choice.enum||choice.oneOf||choice.anyOf||[]).map((v,i)=>typeof v==='string'?{value:v,title:choice.enumNames?.[i]||v}:{value:v.const,title:v.title||v.const});
  let field;if(options.length)field=`<select ${common} ${required} ${f.type==='array'?'multiple':''}>${f.type!=='array'?'<option value="">Choose…</option>':''}${options.map(o=>`<option value="${esc(o.value)}" ${(Array.isArray(value)?value.includes(o.value):value===o.value)?'selected':''}>${esc(o.title)}</option>`).join('')}</select>`;
  else if(f.type==='boolean')field=`<input ${common} type="checkbox" ${value?'checked':''}>`;
  else{const type={integer:'number',number:'number'}[f.type]||{email:'email',uri:'url',date:'date'}[f.format]||'text';field=`<input ${common} type="${type}" value="${esc(value??'')}" ${required} ${type==='number'?`step="${f.type==='integer'?'1':'any'}"`:''} ${f.minimum!==undefined?`min="${f.minimum}"`:''} ${f.maximum!==undefined?`max="${f.maximum}"`:''} maxlength="${f.maxLength||16384}">`;}
  return `<label>${esc(f.title||name)}${field}${f.description?`<small>${esc(f.description)}</small>`:''}</label>`;
 }).join('');
 return `<form class="permission-card elicitation-form" data-elicitation="${esc(p.id)}"><h3>${esc(p.agent)} has a question</h3><p>${esc(p.message)}</p>${fields}<div class="actions"><button type="submit" class="primary">Send answer</button>${actions}</div></form>`;
 }).join('');}
function elicitationValues(form){return Object.fromEntries([...form.querySelectorAll('[data-form-field]')].map(e=>[e.dataset.formField,e.type==='checkbox'?e.checked:e.multiple?[...e.selectedOptions].map(o=>o.value):e.type==='number'?(e.value===''?null:Number(e.value)):e.value]).filter(([,v])=>v!==null&&v!==''));}
async function decideElicitation(id,action,content){await api(`sessions/${session.id}/elicitations/${id}`,'POST',{action,content});const drafts={...(view.elicitation_drafts||{})};delete drafts[id];await cmd({elicitation_drafts:drafts},false);session=await api(`sessions/${session.id}`);if(session.status==='running')updateLive();else await render();}
function bindElicitations(){
 $$('[data-form-decision]').forEach(b=>b.onclick=()=>act(()=>decideElicitation(b.dataset.formId,b.dataset.formDecision)));
 $$('[data-form-open]').forEach(b=>b.onclick=()=>act(()=>decideElicitation(b.dataset.formOpen,'accept')));
 $$('[data-elicitation]').forEach(form=>{
  form.oninput=()=>act(()=>cmd({elicitation_drafts:{...(view.elicitation_drafts||{}),[form.dataset.elicitation]:elicitationValues(form)}},false));
  form.onsubmit=e=>{e.preventDefault();if(form.reportValidity())act(()=>decideElicitation(form.dataset.elicitation,'accept',elicitationValues(form)));};
 });
}
// Same actions used by visible controls; callers still use the authenticated API.
window.observatoryInteractions={
 answer:(id,action,content)=>decideElicitation(id,action,content),
 open:async id=>{const p=session?.elicitations?.find(p=>p.id===id&&p.mode==='url');if(!p)throw Error('External step is no longer active');window.open(p.url,'_blank','noopener,noreferrer');await decideElicitation(id,'accept');},
 draft:(id,content)=>cmd({elicitation_drafts:{...(view.elicitation_drafts||{}),[id]:content}}),
};
function mediaHtml(items=[]){return items.filter(m=>m&&typeof m.data==='string'&&m.data.length<=16*1024*1024&&/^[A-Za-z0-9+/]*={0,2}$/.test(m.data)).slice(0,8).map((m,i)=>{const image=['image/png','image/jpeg','image/webp','image/gif'].includes(m.mime_type),audio=['audio/wav','audio/mpeg'].includes(m.mime_type);const mime=image||audio?m.mime_type:'application/octet-stream';const uri=`data:${mime};base64,${m.data}`,ext=({'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/gif':'gif','audio/wav':'wav','audio/mpeg':'mp3'})[mime]||'bin';return `<div class="generated-media">${image?`<img src="${uri}" alt="Generated image ${i+1}">`:audio?`<audio src="${uri}" controls></audio>`:''}<a href="${uri}" download="generated-${i+1}.${ext}">Download ${image?'image':audio?'audio':'file'}</a></div>`;}).join('');}
function liveProgress(){const p=session?.progress;return `${session?.status==='running'?mediaHtml(p?.media):''}${p&&(session.status==='running'||session.status==='failed'||session.status==='cancelled')&&p.text?`<div class="chat-message"><small>${session.status==='running'?'Responding…':'Interrupted response'}</small><div class="markdown">${renderMarkdown(p.text)}</div></div>`:''}${(p?.tools||[]).length?`<div class="tool-progress" aria-label="Tool progress">${p.tools.map(t=>`<div><span>${esc(t.title||t.kind||'Using a tool')}</span><small>${esc((t.status||'working').replaceAll('_',' '))}</small></div>`).join('')}</div>`:''}${(p?.plan||[]).length?`<ol class="agent-plan">${p.plan.map(i=>`<li><span>${esc(i.content)}</span> <small>${esc((i.status||'pending').replaceAll('_',' '))}</small></li>`).join('')}</ol>`:''}${permissionCards()}${elicitationCards()}${session?.status==='running'&&session.can_cancel?'<button type="button" data-action="cancel-turn">Stop this turn</button>':''}`;}
let agentHistory=null;
async function loadAgentHistory(){if(view.tab!=='chat'||!view.agent_history_open||!endpoint())return;const key=JSON.stringify([endpoint().id,view.agent_history_cursor||null]);if(agentHistory?.key===key)return;try{agentHistory={key,...await api(`endpoints/${endpoint().id}/acp-sessions`,'POST',{action:'list',cursor:view.agent_history_cursor||null})};}catch(e){agentHistory={key,error:e.message};}}
function agentHistoryPanel(){return `<section class="agent-history"><button data-action="agent-history">${view.agent_history_open?'Hide':'Browse'} agent session history</button>${view.agent_history_open?`<p class="muted">Sessions in this connection’s configured folder. Saved conversations in this app remain separate from the agent’s history.</p>${agentHistory?.error?`<p>${esc(agentHistory.error)}</p>`:''}${(agentHistory?.sessions||[]).map(s=>`<div class="row"><span>${esc(s.title)}<small>${esc(s.sessionId)} · ${esc(s.updatedAt)}</small></span>${agentHistory.can_delete?`<button data-history-delete="${esc(s.sessionId)}">Remove from agent history…</button>`:''}</div>`).join('')||'<p>No session entries available.</p>'}<div class="actions"><button data-action="agent-history-refresh">Refresh</button>${agentHistory?.nextCursor?'<button data-action="agent-history-next">Next page</button>':''}${view.agent_history_cursor?'<button data-action="agent-history-first">First page</button>':''}</div>${view.agent_history_delete?`<section class="permission-card" role="alertdialog" aria-label="Remove agent session"><h3>Remove this session from the agent’s history?</h3><p>${esc(view.agent_history_delete)}</p><p>This changes what the agent lists. It does not erase transcripts saved by this app or other clients. An active session in another client may be affected.</p><div class="actions"><button data-action="agent-history-confirm">Remove from agent history</button><button data-action="agent-history-cancel">Keep session</button></div></section>`:''}`:''}</section>`;}
function chat(e){const saved=(data.sessions||[]).filter(s=>s.endpoint_id===e.id);return `<section class="panel"><div class="actions"><h2>${esc(session?.title||'Talk with this agent')}</h2><button data-action="new-chat">New conversation</button>${session?'<button data-action="close-chat">Disconnect</button>':''}</div>${saved.length?select('Saved conversation','saved_session',[['','Choose a conversation'],...saved.map(s=>[s.id,`${s.title} · ${when(s.updated_at)}`])],session?.id||''):''}${session?`<small>Conversation ${esc(session.id)} · ${esc(session.status)}</small>${(session.messages||[]).map(m=>`<div class="chat-message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'You':esc(e.label)} · ${when(m.at)}</small><div class="markdown">${renderMarkdown(m.text)}</div>${mediaHtml(m.media)}</div>`).join('')}${session.error?`<p class="error">${esc(session.error)}</p>`:''}`:'<p class="muted">Start a conversation through this agent’s standard ACP endpoint.</p>'}<div id="turn-progress" aria-live="polite">${liveProgress()}</div><form id="chat-form" data-endpoint="${esc(e.id)}">${area('Message','prompt',view.draft.prompt||'')}<button class="primary" ${session?.status==='running'?'disabled':''}>${session?.status==='running'?'Working…':'Send'}</button></form>${agentHistoryPanel()}<details><summary>Client capabilities</summary><p class="muted">Text, live tool progress, explicit action approvals, structured questions, browser sign-in steps, and session restore when the agent offers it. Filesystem and terminal callbacks are not offered by this client. The agent may provide its own tools.</p></details></section>`;}
function bindLive(){
 $$('[data-history-delete]').forEach(b=>b.onclick=()=>act(()=>cmd({agent_history_delete:b.dataset.historyDelete})));
 bindElicitations();
 $$('[data-permission]').forEach(b=>b.onclick=()=>act(async()=>{const id=session.id;await api(`sessions/${id}/permissions/${b.dataset.permission}`,'POST',{option_id:b.dataset.option??null});session=await api(`sessions/${id}`);if(session.status==='running')updateLive();else await render();}));
 $$('[data-permission-details]').forEach(b=>b.onclick=()=>act(async()=>{await cmd({permission_details:view.permission_details===b.dataset.permissionDetails?null:b.dataset.permissionDetails},false);updateLive();}));
 const stop=$('[data-action="cancel-turn"]');if(stop)stop.onclick=()=>act(()=>action('cancel-turn'));
}
function updateLive(){const target=$('#turn-progress');if(target){target.innerHTML=liveProgress();bindLive();}}

function connections(){return heading('Connections and experiences.','Adapters and interfaces remain independent services.',`<button class="primary" data-action="connect">Connect service</button>`)+cards(data.endpoints.filter(e=>e.kind!=='agent'))+`<section class="panel stack space-top"><h2>Relationships</h2><p class="muted">These records describe connections. Each service still owns its permissions and actual connection setup.</p>${data.links.map(l=>`<div class="row"><span>${esc(data.endpoints.find(e=>e.id===l.from)?.label||'Detached')} → ${esc(data.endpoints.find(e=>e.id===l.to)?.label||'Detached')}</span><span class="badge">${esc(l.relation)}</span></div>`).join('')||'<p>No relationships recorded yet. The API accepts explicit connection records.</p>'}</section>`;}
function updateInventory(){return `<section class="panel stack space-top"><div class="actions"><h2>Installation updates</h2><button data-action="load-all-updates">Check status</button></div>${installationUpdates?Object.entries(installationUpdates).map(([id,u])=>`<div class="row"><div><strong>${esc(data.endpoints.find(e=>e.id===id)?.label||id)}</strong><small>${u.error?esc(u.error):esc((u.helper?.state||'Not checked').replaceAll('_',' '))+(u.helper_connected?'':' · Helper offline')}</small></div><button data-open-updates="${esc(id)}">Open updates</button></div>`).join('')||'<p>No connected installations currently advertise update controls. Check their connections after upgrading.</p>':'<p>See update status from connected installations. Each installation manages its own services and recovery.</p>'}</section>`;}
function hosts(){return heading('Places your agents can live.','Each machine has its own approved installer versions and installation folders.',`<button class="primary" data-action="host">Add machine</button>`)+`<div class="cards">${data.hosts.map(h=>`<section class="card"><div class="eyebrow">${esc(h.transport)}</div><h2>${esc(h.label)}</h2><p class="muted">${esc(h.address||'This machine')}</p>${h.recipes.map(r=>`<div class="row"><span>${esc(r.id)}</span><small>${esc(r.version)}</small></div>`).join('')}<button data-install-host="${h.id}">Create an agent</button></section>`).join('')}</div><section class="panel stack space-top"><h2>Installations</h2>${data.jobs.map(j=>`<div class="row"><span>${esc(j.plan?.name||j.id)}<small>${esc(j.note)}</small></span><div class="actions"><span class="badge ${j.status==='completed'?'ok':''}">${esc(j.status)}</span><button data-job="${j.id}">View result</button></div></div>`).join('')||'<p class="muted">New installations will appear here.</p>'}</section>`+updateInventory();}
function work(){return heading('Responsibilities across your agents.','Read work at its source. Each agent owns its commitments and evidence.',`<button data-action="load-all-work">Load work</button>`)+`<div id="all-work">${remote?Object.entries(remote).map(([id,v])=>`<section class="panel stack"><h2>${esc(data.endpoints.find(e=>e.id===id)?.label||id)}</h2>${v.error?`<p class="muted">${esc(v.error)}</p>`:renderWork(v,data.endpoints.find(e=>e.id===id))}</section>`).join(''):empty('Bring commitments into view.','Load the agents that offer a work-management interface. ACP-only agents remain available without this optional feature.','load-all-work','Load work')}</div>`;}
let experimentTranscript=null;
async function loadExperimentTranscript(){
 if(view.screen!=='experiments'||!view.experiment_id)return;
 const record=data.experiments.find(r=>r.id===view.experiment_id);
 if(!record)return;
 if(experimentTranscript?.id===record.id&&experimentTranscript.revision===record.revision)return;
 try{experimentTranscript=await api(`experiments/${record.id}/transcript`);}
 catch(e){experimentTranscript={id:record.id,revision:record.revision,error:e.message};}
}
function experiments(){
 const selected=data.experiments.find(r=>r.id===view.experiment_id);
 if(selected){
  const kinds={simulated_human:'Simulated human',support_agent:'Agent',human:'Human',operator_cue:'Operator cue',membership:'Room membership',protocol_fixture:'Protocol fixture'};
  const transcript=experimentTranscript?.id===selected.id?experimentTranscript:null;
  return heading(selected.label,'Recorded public contributions. Private drafts and unpublished responses are excluded.','<button data-action="refresh">Refresh</button><button data-action="experiments-back">All experiments</button>')+
   `<section class="panel stack"><div class="markdown">${renderMarkdown(selected.summary)}</div><button data-action="experiment-measurements">${view.experiment_measurements?'Hide':'Show'} measurements</button>${view.experiment_measurements?`<pre class="detail" id="experiment-measurements">${esc(pretty(selected.measurements))}</pre>`:''}</section>`+
   (transcript?.error?`<p class="error">${esc(transcript.error)}</p>`:transcript?.messages?.length?`<section class="stack" aria-label="Experiment transcript">${transcript.messages.map(m=>`<article class="panel experiment-message"><div class="card-head"><strong>${esc(m.speaker)}</strong><span class="badge">${esc(kinds[m.kind]||m.kind)}</span></div><small>${esc(m.room)}${m.at?' · '+esc(m.at):''}</small><div class="markdown">${renderMarkdown(m.text)}</div></article>`).join('')}</section>`:empty('No public transcript attached.','The experiment runner can attach its public messages through the transcript API.'));
 }
 return heading('Learn from each run.','Compare outcomes, participation, and technical reliability separately.','<button data-action="refresh">Refresh</button>')+(data.experiments.length?`<div class="cards">${data.experiments.map(r=>`<section class="card"><span class="badge">${esc(r.status||'reported')}</span><h2>${esc(r.label)}</h2><div class="markdown">${renderMarkdown(r.summary)}</div><div class="actions"><button data-experiment="${esc(r.id)}">${r.transcript_count?'Read conversation':'View results'}</button>${r.report_url?`<a href="${esc(r.report_url)}" target="_blank" rel="noopener">Open run report ↗</a>`:''}</div></section>`).join('')}</div>`:empty('No runs connected yet.','Experiment runners can submit reports through the API. Submitted results retain their source; the Observatory does not turn a self-report into independent verification.'));
}
function activity(){return heading('Changes worth knowing about.','Connections, operations, installations, and completed turns.',`<button data-action="refresh">Refresh</button>`)+`<section class="panel">${data.events.map(e=>`<div class="row"><span>${esc(e.kind.replaceAll('.',' '))}<small>${esc(e.data?.label||e.data?.operation||e.data?.status||e.data?.name||'')}</small></span><small>${when(e.at)}</small></div>`).join('')||'<p class="muted">Activity will appear as you connect and work with agents.</p>'}</section>`;}
function settings(){return heading('Access under your control.','Use your machine account here, or scoped credentials for other tools.')+`<section class="panel stack"><h2>Connection credentials</h2><p class="muted">Store credentials once, then refer to them by name. Values are never returned by this interface.</p><button data-action="credentials">Store credential</button><details><summary>Programmatic access</summary><p>All operations use the versioned <code>/api/v1</code> interface. Scopes separate observation, management, conversation, installation, and view control.</p><p>The CLI uses the same API. Create scoped access through <code>POST /api/v1/tokens</code>.</p></details></section>`;}
function modal(){if(!view.modal)return '';const d=view.draft||{};let name='',body='',submit='Save';
 if(view.modal==='connect'||view.modal==='edit'){name=view.modal==='edit'?'Edit connection':'Connect an agent or service';submit=view.modal==='edit'?'Save connection':'Connect';body=field('Name','label',d.label)+select('What is it?','kind',[['agent','Agent'],['adapter','Adapter'],['experience','Conversation experience'],['workshop','Persona Workshop']],d.kind||'agent')+field('Management address','address',d.address,'url','Its HTTPS address, including the port. Leave empty for an ACP-only agent.')+select('Management provider','provider',[['agent-instance','Agent Instance'],['slack-adapter','Slack ACP Adapter'],['persona-workshop','Persona Workshop'],['generic-json','Custom provider']],d.provider||'agent-instance')+field('Credential name','credential_ref',d.credential_ref,'text','A credential already stored here. Use Access to add one.')+select('Access','access',[['observe','Observe'],['manage','Manage and observe']],d.access||'observe')+`<details ${d.advanced?'open':''}><summary>ACP and other options</summary>${field('ACP executable','command',d.command)}${area('Arguments (JSON array)','args',d.args||'[]')}${field('Working folder','cwd',d.cwd)}${field('Standalone dashboard address','ui_url',d.ui_url,'url')}</details>`;}
 else if(view.modal==='credentials'){name='Store a connection credential';body=field('Credential name','name',d.name)+field('Credential value','credential_value','','password','This value stays out of shared view state. Automation stores it through the credential API.');}
 else if(view.modal==='host'){name='Add a machine';body=`<p class="muted">Machine access is separate from agent access. Choose explicit installers and folders for this host.</p>`+area('Machine configuration','host_config',d.host_config||pretty({label:'Agent host',transport:'ssh',address:'agent-host',install_roots:['/home/operator/.local/share/agent-instance'],recipes:[{id:'agent-instance',version:'pinned-version',argv:['/absolute/path/to/installer','--home','{home}','--name','{name}','--port','{port}']}]}));}
 else if(view.modal==='job'){name='Installation result';submit='';const j=remote?.job;body=j?`<span class="badge">${esc(j.status)}</span><h3>${esc(j.plan?.name||'Agent installation')}</h3><p class="muted">${esc(j.note)}</p><p>Open the new service’s setup address from the installer output below. It keeps its own account and configuration.</p><div class="actions"><button type="button" data-action="refresh-job">Refresh result</button></div><div class="actions">${installerLinks(remote.stdout,j.plan)}</div><h3>Installer output</h3><pre class="detail">${esc(remote.stdout)}</pre>${remote.stderr?`<details><summary>Diagnostics</summary><pre class="detail">${esc(remote.stderr)}</pre></details>`:''}`:'<p>Loading installation result…</p>'; }
 else if(view.modal==='install'){name='Create an independent agent';submit='Install';const h=data.hosts.find(h=>h.id===d.host_id)||data.hosts[0];body=data.hosts.length?select('Machine','host_id',data.hosts.map(h=>[h.id,h.label]),h.id)+select('Installer','recipe_id',h.recipes.map(r=>[r.id,`${r.id} · ${r.version}`]),d.recipe_id||h.recipes[0]?.id)+field('Agent name','name',d.name)+field('Installation folder','home',d.home||`${h.install_roots[0]}/new-agent`)+field('Port (0 chooses one)','port',d.port||0,'number')+'<p class="muted">The installer creates its own folder and service. Its resulting address can then be connected here.</p>':'<p>Add a machine and an installer first.</p>';}
 return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(name)}</h2><button class="quiet" data-action="close" aria-label="Close">✕</button></div><form id="modal-form">${body}<div class="actions">${submit?`<button class="primary">${submit}</button>`:''}<button type="button" data-action="close">${submit?'Cancel':'Close'}</button></div></form></section></div>`;}
async function render(){document.title="Agent Observatory";if(!auth.authenticated)return login();if(view.selected_id&&!endpoint())await load();await syncSession();await loadOptionalView();await loadAgentHistory();await loadExperimentTranscript();if(view.modal==='job'&&remote?.job?.id!==view.draft.job_id)await loadJob(view.draft.job_id);const selected=endpoint();document.title=selected&&['agents','work'].includes(view.screen)?`${selected.label}: Agent Observatory`:'Agent Observatory';const content=({agents,connections,hosts,work,experiments,activity,settings}[view.screen]||agents)();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="mark">a·</span><span>Agent Observatory<br><small>INDEPENDENT BY DESIGN</small></span></div><nav class="nav">${Object.entries(screens).map(([id,label])=>`<button class="${view.screen===id?'active':''}" data-nav="${id}">${label}</button>`).join('')}</nav><footer><small>Connected as ${esc(auth.owner)}</small><small id="view-label">View ${esc(view.id.slice(0,8))} · ${view.revision}</small><button class="quiet" data-action="logout">Sign out</button></footer></aside><div class="content"><header class="topbar"><span>${esc(title())}</span><small>View ${view.id.slice(0,8)} · ${esc(view.controller)}</small></header><main class="main">${content}</main></div></div>${modal()}`;bind();if(view.focus){const el=document.getElementById(view.focus);el?.focus({preventScroll:true});}if(view.scroll)window.scrollTo(view.scroll.x,view.scroll.y);await api(`views/${view.id}/ack`,'POST',{revision:view.revision});}
function login(){ $('#app').innerHTML=`<main class="login panel"><div class="brand"><span class="mark">a·</span><span>Agent Observatory</span></div><h1>Your agents, together.</h1><p class="muted">Sign in with the account on this machine.</p><form id="login-form">${field('Username','username',auth.owner||'')}${field('Password','password','','password')}<button class="primary">Sign in</button><p id="login-error" class="error" hidden></p></form></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();try{auth=await api('/auth/login','POST',Object.fromEntries(new FormData(e.target)));await ready();}catch(err){$('#login-error').hidden=false;$('#login-error').textContent=err.message;}};}
let draftTimer,filterTimer,scrollTimer;function saveDraft(form){clearTimeout(draftTimer);draftTimer=setTimeout(()=>act(async()=>{const draft={...view.draft};for(const[k,v]of new FormData(form)){if(k==='credential_value')continue;draft[k]=k==='port'?Number(v):v;}await cmd({draft},false);}),250);}
async function syncSession(){
 const id=view.session_id,selected=view.selected_id;
 if(!id){session=null;return;}
 const candidate=session?.id===id?session:await api(`sessions/${id}`);
 if(view.session_id!==id||view.selected_id!==selected)return;
 if(candidate.endpoint_id!==selected){session=null;await cmd({session_id:null},false);toast('That conversation belongs to another agent. Select a conversation for this agent.');return;}
 session=candidate;
}
function installerLinks(output,plan){
 const urls=[...new Set(String(output||'').split('\n').map(line=>line.trim()).filter(line=>/^https?:\/\/[^\s]+$/.test(line)))];
 const preferred=String(plan?.address||'').split('@').pop();
 const rank=raw=>{try{const u=new URL(raw);return (u.hostname===preferred?0:2)+(u.protocol==='https:'?0:1);}catch{return 9;}};urls.sort((a,b)=>rank(a)-rank(b));
 return urls.flatMap(raw=>{try{const u=new URL(raw);if(u.username||u.password||u.search||u.hash||['localhost','127.0.0.1','[::1]'].includes(u.hostname))return [];return [`<a class="button" target="_blank" rel="noopener noreferrer" href="${esc(u.href)}">${u.protocol==='https:'?'Open setup':'Connection help'} · ${esc(u.host)}</a>`];}catch{return [];}}).slice(0,16).join('');
}
async function loadJob(id){const [job,stdout,stderr]=await Promise.all([api(`jobs/${id}`),api(`jobs/${id}/log/stdout`),api(`jobs/${id}/log/stderr`)]);remote={job,stdout:stdout.text,stderr:stderr.text};}
function bind(){bindLive();$$('[data-experiment]').forEach(b=>b.onclick=()=>act(()=>cmd({screen:'experiments',experiment_id:b.dataset.experiment,experiment_measurements:false,scroll:null}))); const embedded=$('iframe.embedded');if(embedded)embedded.onload=()=>{setTimeout(showAgentScreen,400);};
 $$('[data-own-screen]').forEach(b=>b.onclick=()=>act(()=>cmd({screen:'agents',selected_id:b.dataset.endpoint||view.selected_id,tab:'embedded',draft:{embedded_route:b.dataset.ownScreen,embedded_work:b.dataset.work||''}})));
 $$('[data-memory-details]').forEach(b=>b.onclick=()=>act(()=>cmd({draft:{...view.draft,memory_details:view.draft.memory_details===b.dataset.memoryDetails?'':b.dataset.memoryDetails}})));
 $$('[data-run-report]').forEach(b=>b.onclick=()=>act(()=>cmd({draft:{...view.draft,run_report:view.draft.run_report===b.dataset.runReport?'':b.dataset.runReport}})));const saved=$('#f-saved_session');if(saved)saved.onchange=()=>act(async()=>{session=saved.value?await api(`sessions/${saved.value}`):null;await cmd({session_id:session?.id||null});});
 $$('[data-nav]').forEach(b=>b.onclick=()=>act(async()=>{remote=null;session=null;await cmd({screen:b.dataset.nav,experiment_id:null,experiment_measurements:false,selected_id:null,session_id:null,tab:'overview',modal:null,draft:{},filter:'',scroll:null,focus:null});}));
 $$('[data-open]').forEach(b=>b.onclick=()=>act(async()=>{remote=null;session=null;await cmd({screen:'agents',selected_id:b.dataset.open,session_id:null,tab:'overview',scroll:null});}));
 $$('[data-tab]').forEach(b=>b.onclick=()=>act(async()=>{remote=null;await cmd({tab:b.dataset.tab,scroll:null});}));
 $$('[data-action]').forEach(b=>b.onclick=()=>act(()=>action(b.dataset.action)));
 $$('[data-open-updates]').forEach(b=>b.onclick=()=>act(async()=>{remote=null;await cmd({screen:'agents',selected_id:b.dataset.openUpdates,tab:'updates'});}));
 $$('[data-update-action]').forEach(b=>b.onclick=()=>act(async()=>{await api(`endpoints/${endpoint().id}/operations/request-update`,'POST',{action:b.dataset.updateAction,request_id:crypto.randomUUID()});remote=await api(`endpoints/${endpoint().id}/operations/updates`,'POST',{});await render();}));
 $$('[data-operation]').forEach(b=>b.onclick=()=>act(async()=>{remote=await api(`endpoints/${endpoint().id}/operations/${b.dataset.operation}`,'POST',{});await render();}));
 $$('[data-lifecycle]').forEach(b=>b.onclick=()=>act(async()=>{await api(`endpoints/${endpoint().id}/operations/lifecycle`,'POST',{action:b.dataset.lifecycle});toast('Lifecycle request applied');await action('inspect');}));
 $$('[data-job]').forEach(b=>b.onclick=()=>act(async()=>{await loadJob(b.dataset.job);await cmd({modal:'job',draft:{job_id:b.dataset.job}});}));
 $$('[data-install-host]').forEach(b=>b.onclick=()=>act(()=>cmd({modal:'install',draft:{host_id:b.dataset.installHost}})));
 const search=$('#search');if(search)search.oninput=()=>{clearTimeout(filterTimer);filterTimer=setTimeout(()=>act(()=>cmd({filter:search.value,focus:'search'})),350);};
 const mf=$('#modal-form');if(mf){mf.oninput=()=>saveDraft(mf);mf.onchange=e=>{if(e.target.name==='host_id')act(()=>cmd({draft:{...view.draft,host_id:e.target.value}}));else saveDraft(mf);};mf.onsubmit=e=>{e.preventDefault();clearTimeout(draftTimer);act(()=>submit(Object.fromEntries(new FormData(mf))));};}
 const cf=$('#chat-form');if(cf){cf.oninput=()=>saveDraft(cf);cf.onsubmit=e=>{e.preventDefault();clearTimeout(draftTimer);act(async()=>{const target=cf.dataset.endpoint;if(view.selected_id!==target)throw Error('The selected agent changed. Review your message before sending.');await syncSession();if(session&&session.endpoint_id!==target)throw Error('This conversation belongs to another agent.');if(!session)session=await api('sessions','POST',{endpoint_id:target,title:'Observatory conversation'});await cmd({session_id:session.id},false);session=await api(`sessions/${session.id}/prompt`,'POST',{text:new FormData(cf).get('prompt'),request_id:crypto.randomUUID()});await cmd({draft:{}});});};}
 const configInput=$('#f-configuration');if(configInput)configInput.oninput=()=>{clearTimeout(draftTimer);draftTimer=setTimeout(()=>act(()=>cmd({draft:{...view.draft,configuration:configInput.value}},false)),300);};
}
async function action(name){
 if(name==='agent-history')return cmd({agent_history_open:!view.agent_history_open,agent_history_cursor:null,agent_history_delete:null});
 if(name==='agent-history-cancel')return cmd({agent_history_delete:null});
 if(name==='agent-history-next')return cmd({agent_history_cursor:agentHistory?.nextCursor||null});
 if(name==='agent-history-first')return cmd({agent_history_cursor:null});
 if(name==='agent-history-refresh'){agentHistory=null;return render();}
 if(name==='agent-history-confirm'){await api(`endpoints/${endpoint().id}/acp-sessions`,'POST',{action:'delete',session_id:view.agent_history_delete,confirm:true});agentHistory=null;await load();return cmd({agent_history_delete:null});}
if(name==='experiments-back')return cmd({experiment_id:null,experiment_measurements:false,scroll:null});if(name==='experiment-measurements')return cmd({experiment_measurements:!view.experiment_measurements});const e=endpoint();if(['connect','host','credentials','install'].includes(name))return cmd({modal:name,draft:{}});if(name==='close')return cmd({modal:null,draft:{},focus:null});if(name==='back'){remote=null;return cmd({selected_id:null,session_id:null,tab:'overview'});}if(name==='refresh'){await load();return render();}if(name==='logout'){await api('/auth/logout','POST',{});auth.authenticated=false;return login();}
 if(name==='show-agent-screen'){showAgentScreen();return;}
 if(name==='refresh-job'){await loadJob(view.draft.job_id);return render();}
 if(name==='edit'){return cmd({modal:'edit',draft:{label:e.label,kind:e.kind||'agent',address:e.management?.base_url||'',provider:e.management?.provider||'agent-instance',credential_ref:e.management?.credential_ref||'',access:e.management?.access||'observe',command:e.acp?.command||'',args:pretty(e.acp?.args||[]),cwd:e.acp?.cwd||'',ui_url:e.ui_url||'',advanced:!!e.acp}});}
 if(name==='inspect'){const o=await api(`endpoints/${e.id}/inspect`,'POST',{});if(o.health==='reachable'&&!e.management.expected_id){const id=o.instance_id||o.descriptor?.instance_id||o.descriptor?.id;if(id){const b=clean(e);b.management={...e.management,expected_id:id};await api(`endpoints/${e.id}`,'PUT',{...b,expected_revision:e.revision});}}await load();await render();return;}
 if(name==='probe'){try{const r=await api(`endpoints/${e.id}/probe`,'POST',{});toast(`ACP connected: ${r.agentInfo?.title||r.agentInfo?.name||'compatible agent'}`);}finally{await load();await render();}return;}
 if(name==='refresh-all'){let failed=0;for(const e of data.endpoints){for(const operation of [...(e.management?['inspect']:[]),...(e.acp?['probe']:[])]){try{const result=await api(`endpoints/${e.id}/${operation}`,'POST',{});if(result.health==='unavailable')failed++;}catch{failed++;}}}await load();await render();toast(failed?`Checks complete. ${failed} connection${failed===1?'':'s'} need attention.`:'Connections checked');return;}
 if(name==='detach'){await api(`endpoints/${e.id}`,'DELETE',{expected_revision:e.revision});await load();return cmd({selected_id:null,session_id:null,tab:'overview'});}
 if(name==='cancel-turn'){await api(`sessions/${session.id}/cancel`,'POST',{});toast('Stopping this turn. Work already performed is not undone.');return;}
 if(name==='close-chat'){session=await api(`sessions/${session.id}/close`,'POST',{});return render();}
 if(name==='new-chat'){session=await api('sessions','POST',{endpoint_id:e.id,title:'Observatory conversation'});await load();return cmd({session_id:session.id});}
 if(name==='load-all-updates'){installationUpdates={};await Promise.all(data.endpoints.filter(e=>supports(e,'updates')).map(async e=>{try{installationUpdates[e.id]=await api(`endpoints/${e.id}/operations/updates`,'POST',{});}catch(err){installationUpdates[e.id]={error:err.message};}}));return render();}
 if(name==='load-all-work'){remote={};for(const e of data.endpoints.filter(e=>e.management?.provider==='agent-instance')){try{remote[e.id]=await api(`endpoints/${e.id}/operations/work`,'POST',{});}catch(err){remote[e.id]={error:err.message};}}return render();}
 if(name==='validate-config'||name==='apply-config'){const b=JSON.parse($('#f-configuration').value);const payload=name==='apply-config'&&remote.revision!==undefined?{expected_revision:remote.revision,config:b}:b;await api(`endpoints/${e.id}/operations/${name}`,'POST',payload);toast(name==='validate-config'?'Configuration is valid':'Configuration applied');if(name==='apply-config'){remote=await api(`endpoints/${e.id}/operations/config`,'POST',{});await cmd({draft:{}},false);}return render();}
}
function clean(e){return Object.fromEntries(['label','kind','acp','management','ui_url','notes'].filter(k=>e[k]!==undefined).map(k=>[k,e[k]]));}
async function submit(d){if(view.modal==='credentials'){await api('credentials','POST',{name:d.name,value:d.credential_value});toast('Credential stored');}
 else if(view.modal==='host'){await api('hosts','POST',JSON.parse(d.host_config));toast('Machine connected');}
 else if(view.modal==='job'){return;}
 else if(view.modal==='install'){const b={...d,port:Number(d.port),request_id:crypto.randomUUID()};const plan=await api('install/plan','POST',b);await api('install','POST',{...b,plan_digest:plan.plan_digest});toast('Installation started');}
 else {const previous=view.modal==='edit'?endpoint():null;let b={...(previous?.notes?{notes:previous.notes}:{}),label:d.label,kind:d.kind};if(d.address){b.management={...(previous?.management?.provider===d.provider?previous.management:{}),base_url:d.address.replace(/\/$/,''),provider:d.provider,credential_ref:d.credential_ref,access:d.access};if(previous?.management?.base_url!==b.management.base_url)delete b.management.expected_id;}if(d.command)b.acp={...(previous?.acp||{}),transport:'stdio',command:d.command,args:JSON.parse(d.args||'[]'),cwd:d.cwd};if(d.ui_url)b.ui_url=d.ui_url.replace(/\/$/,'');else if(d.address)b.ui_url=d.address.replace(/\/$/,'');const old=endpoint();if(view.modal==='edit'){if(old.management?.expected_id&&old.management.base_url===b.management?.base_url)b.management.expected_id=old.management.expected_id;b=await api(`endpoints/${old.id}`,'PUT',{...b,expected_revision:old.revision});}else b=await api('endpoints','POST',b);if(b.management){const o=await api(`endpoints/${b.id}/inspect`,'POST',{});if(o.health==='reachable'){const id=o.instance_id||o.descriptor?.instance_id||o.descriptor?.id;if(id)await api(`endpoints/${b.id}`,'PUT',{...clean(b),management:{...b.management,expected_id:id},expected_revision:b.revision});}}toast('Connection saved');}
 await load();await cmd({modal:null,draft:{},focus:null});}
async function ready(){await load();const id=sessionStorage.getItem('observatory-view');try{view=id?await api(`views/${id}`):await api('views','POST',{});}catch{view=await api('views','POST',{});}sessionStorage.setItem('observatory-view',view.id);const link=new URL(location.href);const linked=link.searchParams.get('conversation');if(linked){try{const saved=await api(`sessions/${linked}`);if(saved.endpoint_id!==link.searchParams.get('agent'))throw Error('This conversation belongs to another agent.');await cmd({screen:'agents',selected_id:saved.endpoint_id,tab:'chat',session_id:saved.id},false);}catch(e){toast(e.message);}link.searchParams.delete('conversation');link.searchParams.delete('agent');history.replaceState(null,'',link);}if(view.session_id){try{session=await api(`sessions/${view.session_id}`);}catch{session=null;}}await render();}
window.addEventListener('scroll',()=>{if(!view||!auth.authenticated)return;clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{if(!busy)act(()=>cmd({scroll:{x:Math.round(window.scrollX),y:Math.round(window.scrollY)}},false));},400);},{passive:true});
setInterval(async()=>{if(!auth.authenticated||!view||busy||polling)return;polling=true;try{const next=await api(`views/${view.id}`);if(busy||next.revision<view.revision)return;if(next.revision!==view.revision){view=next;remote=null;if(view.session_id){session=await api(`sessions/${view.session_id}`);}else{session=null;}await load();await render();}else if(view.screen==='hosts'&&!view.modal&&data.jobs.some(j=>['running','queued'].includes(j.status))){await load();await render();}else if(session?.status==='running'){const old=JSON.stringify([session.progress,session.permissions,session.elicitations,session.can_cancel]);session=await api(`sessions/${session.id}`);if(session.status!=='running')await render();else if(old!==JSON.stringify([session.progress,session.permissions,session.elicitations,session.can_cancel]))updateLive();}}catch{}finally{polling=false;}},1200);
try{auth=await api('/auth/session');if(auth.authenticated)await ready();else login();}catch(e){$('#app').innerHTML=`<main class="login panel"><h1>Connection unavailable</h1><p>${esc(e.message)}</p></main>`;}
